typedef unsigned int uint32;

class stringx
{
  char data[16];
public:
  stringx(const char *, int = -1);
  ~stringx();
};

struct nglMaterial
{
  uint32 Flags;
};

struct nglMeshSection
{
  nglMaterial *Material;
  char padding[60];
};

struct nglMesh
{
  char padding[84];
  int NSections;
  nglMeshSection *Sections;
};

struct entity
{
  char padding[8];
  struct vtable_t
  {
    char padding[632];
    short adjustment;
    short reserved;
    nglMesh *(*get_mesh)(void *);
  } *vtable;

  nglMesh *get_mesh()
  {
    vtable_t *table = vtable;
    return table->get_mesh((char *)this + table->adjustment);
  }
};

class camera
{
public:
  void adjust_geometry_pipe(bool = false);
};

class game
{
public:
  void set_current_camera(camera *);
};

class world_dynamics_system
{
public:
  class entity_list
  {
  public:
    class const_iterator
    {
      entity **current;
    public:
      const_iterator(entity **p) : current(p) {}
      entity *operator*() const { return *current; }
      const_iterator &operator++() { ++current; return *this; }
      bool operator!=(const const_iterator &other) const
      {
        return current != other.current;
      }
    };

    entity **first;
    entity **last;
    const_iterator begin() const { return const_iterator(first); }
    const_iterator end() const { return const_iterator(last); }
  };

  char padding[100];
  entity_list entities;

  void load_fe_scene(const stringx &, const stringx &);
  void recompute_all_sectors();
  camera *get_marky_cam_ptr() { return *(camera **)((char *)this + 364); }
  const entity_list &get_entities() const { return entities; }
  void load_scene_anim(const stringx &);
};

class FEEntityManager
{
  char padding[532];
  camera *fe_camera;
  camera *active_camera;
public:
  void LoadSet();
};

extern world_dynamics_system *g_world_ptr;
extern game *g_game_ptr;
extern float PROJ_ZOOM;

enum { NGLMAT_FOG = 0x40000 };

void FEEntityManager::LoadSet()
{
	if(fe_camera) return;

	g_world_ptr->load_fe_scene("levels\\frontend", "newfrontend");

	g_world_ptr->recompute_all_sectors();

	fe_camera = g_world_ptr->get_marky_cam_ptr();
	g_game_ptr->set_current_camera(fe_camera);
	PROJ_ZOOM = .6;
	fe_camera->adjust_geometry_pipe();
	active_camera = fe_camera;

	// tedious way to remove material fog flags
	world_dynamics_system::entity_list::const_iterator ei = g_world_ptr->get_entities().begin();
	world_dynamics_system::entity_list::const_iterator ei_end = g_world_ptr->get_entities().end();
	for ( ; ei!=ei_end; ei++ )
	{
		entity* ent = *ei;
		if(ent)
		{
			nglMesh *Mesh = ent->get_mesh();
			if(Mesh)
			{
				for(int i=0; i<(signed)Mesh->NSections; i++)
				{
					nglMeshSection* Section = &Mesh->Sections[i];
					nglMaterial* Material = Section->Material;
					Material->Flags &= ~NGLMAT_FOG;
				}
			}
		}
	}
	g_world_ptr->load_scene_anim("levels\\frontend\\animations\\NewFE_Camera.SNMX");
}
